// pad themselves with set-dressing inventories.
const text = String($json.output !== undefined ? $json.output : ($json.text || '')).replace(/\r\n/g, '\n').trim();
const outline = ($('Generate Outline').first().json.output || {});
const planned = outline.chapters || [];
const rp = $('Receive Project Data').first().json;
const scenes = Math.max(1, Math.ceil(Number(rp.Lenght || 64) / 8) - 1);
const target = scenes * 22;
// The floor used to be 90% of the target, and that one number is what
// turned a thin story into description: a draft with fewer events than the
// runtime was sent back to be lengthened, repetition and inventories were
// counted (2026-09-02/04), and the padding moved to the one outlet still
// unmeasured — the picture spoken aloud. Since 2026-09-13 the length is a
// CEILING: a film shorter than ordered is correct, and only a draft under
// 55% of the target — a broken one, not a short one — goes back for length.
const min = Math.round(target * 0.55);
const max = Math.round(target * 1.12);
const blocks = text.split(/\n(?=\[CHAPTER\s+\d+\s*:)/i).map(b => b.trim()).filter(Boolean);
const chapters = [];
for (const block of blocks) {
  const h = block.match(/^\[CHAPTER\s+(\d+)\s*:\s*([^\]]*)\]\s*\n?/i);
  if (!h) continue;
