// Rebuilds, from the database alone, everything the in-loop regeneration
// holds in execution memory: the prompt, the aspect ratio, and the SAME
// reference set the batch attaches — cast sheets, object sheets, the set
// plate, the previous scene's picture last — so a picture re-rolled from the
// site is anchored exactly like its neighbours. One model string, in three
// places that must agree.
const MODEL = 'nano-banana-2';
const scene = $('IR Load Scene').first().json;
const f = scene.fields || {};
const project = ($('IR Load Project').first().json || {}).fields || {};
const all = ($('IR Load Siblings').first().json.records || [])
  .slice()
  .sort((a, b) => (Number((a.fields || {})['Ordine Scenă']) || 0) - (Number((b.fields || {})['Ordine Scenă']) || 0));

let prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
if (!prompt) throw new Error('Scene ' + scene.id + ' has no image prompt.');
// Reviewer feedback steers the re-roll instead of repeating it blindly.
const note = String(f['Observații Scenă'] || '').trim();
if (note && !/REJECTED|FAILED|AUTO-REWRITE/i.test(note)) {
  prompt += '\n\nADJUSTMENT REQUEST — the new image MUST follow this: ' + note;
}
const rejectedBefore = /REJECTED|AUTO-REWRITE/i.test(note);

let opts = {};
try { opts = JSON.parse(project['Editing Options'] || '{}') || {}; } catch (e) {}
let bible = {};
try { bible = JSON.parse(project['Story Bible'] || '{}') || {}; } catch (e) {}
const isFirstScene = Number(f['Ordine Scenă']) === 1;
const userRefId = isFirstScene ? String(opts.refImageMediaId || '') : '';
if (isFirstScene && !userRefId && String(opts.refImage || '').startsWith('http')) {
  console.log('IR: scene 1 has a reference photo but no refImageMediaId yet (the next batch pass uploads it) — regenerating without it.');
}
// Previous scene's image = palette reference, last, by media id; dropped when
// consecutive prompts are largely the same words (the text alone keeps them
// consistent and the reference would collapse the composition).
const idx = all.findIndex((r) => r.id === scene.id);
let prevId = '';
if (idx > 0 && !rejectedBefore) {
  const prev = all[idx - 1].fields || {};
  prevId = String(prev['Image Media ID'] || '');
  const wordSet = (s) => new Set(String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter((w) => w.length > 3));
  const A = wordSet(prompt), B = wordSet(prev['Imagine First Frame']);
  if (A.size && B.size) {
    let hit = 0;
    for (const w of A) if (B.has(w)) hit++;
    if (hit / Math.max(A.size, B.size) > 0.55) prevId = '';
  }
}
const aspect = project['Format'] === '9:16' ? '9:16' : '16:9';
// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
// regen). Change one, change all three: a re-rolled picture built from
// different references than its neighbours is the drift this exists to stop.
//
// Consistency comes from PICTURES the model is anchored to, never from prose:
//   - cast sheets   (castRefs / castSheets)   one per character, turnaround or portrait
//   - object sheets (objectRefs)              one per hero object (a car, a machine)
//   - set plates    (locationRefs)            one per bible location, wide, empty
//   - the producer's own photo                ground truth on scene 1
//   - the previous frame                      LAST, palette only
// Who and where come from the scene's own tags (`char:`, `obj:`, `loc:`),
// written by the segmenter; films made before the tags existed fall back to
// name matching on Prompt Vizual, exactly as the cast sheet did.
const CONS = (function () {
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const tagsOf = (f) => (Array.isArray(f['Tag-uri Scenă']) ? f['Tag-uri Scenă'] : []).map((t) => String(t));
  const tagged = (f, prefix) => tagsOf(f).filter((t) => t.startsWith(prefix)).map((t) => t.slice(prefix.length).trim()).filter(Boolean);
  const mentions = (text, name, allGivens) => {
    const full = norm(name);
    const given = norm(name.split(/\s+/)[0] || '');
    const keys = (allGivens || []).filter((g) => g && g === given).length > 1 ? [full] : [full, given];
    return keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text));
  };
  // Which bible entries are IN this scene: tags first (exact names the
  // segmenter chose from the bible), name matching second.
  function present(f, entries, prefix, textFields) {
    const names = entries.map((e) => String((e || {}).name || '').trim()).filter(Boolean);
    const fromTags = tagged(f, prefix).map(norm);
    if (fromTags.length) return names.filter((n) => fromTags.includes(norm(n)));
    const text = ' ' + norm(textFields.map((k) => f[k] || '').join(' ')) + ' ';
    const givens = names.map((n) => norm(n.split(/\s+/)[0] || ''));
    return names.filter((n) => mentions(text, n, givens));
  }
  function plan(a) {
    // a: { f, opts, bible, prompt, prevId, userRefId, isFirstScene, afterRefusal, strict, strictNotes }
    const opts = a.opts || {}, bible = a.bible || {}, f = a.f || {};
    const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
    const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
    const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
    const locationRefs = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
    const chars = Array.isArray(bible.characters) ? bible.characters : [];
    const objs = Array.isArray(bible.objects) ? bible.objects : [];
    const locs = Array.isArray(bible.locations) ? bible.locations : [];
    const refs = []; // {id, role, name}
    const used = { cast: [], objects: [], location: '', user: false, palette: false };
    if (a.afterRefusal) {
      // A refusal is likeliest about a face; nothing is attached, the prompt
      // rewrite alone carries the retry. Same rule as before the sheets.
      return { refs, used, prompt: a.prompt };
    }
    const protagonist = (() => {
      const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
      return String(((byRole || chars[0]) || {}).name || '');
    })();
    if (a.isFirstScene && a.userRefId) { refs.push({ id: a.userRefId, role: 'user', name: protagonist }); used.user = true; }
    // Cast: leads (turnaround sheets) first, then portraits; two at most —
    // a third sheet crowds the composition (measured on the cast sheet port).
    const inScene = present(f, chars, 'char:', ['Prompt Vizual']).filter((n) => castRefs[n]);
    inScene.sort((x, y) => ((castSheets[y] || {}).kind === 'turnaround') - ((castSheets[x] || {}).kind === 'turnaround'));
    for (const n of inScene) {
      if (used.user && norm(n) === norm(protagonist)) continue; // the photo is truer than the sheet
      if (used.cast.length >= 2) break;
      refs.push({ id: castRefs[n], role: 'cast', name: n }); used.cast.push(n);
    }
    const objsIn = present(f, objs, 'obj:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => objectRefs[n]);
    for (const n of objsIn) { if (used.objects.length >= 1) break; refs.push({ id: objectRefs[n], role: 'object', name: n }); used.objects.push(n); }
    const locIn = present(f, locs, 'loc:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => locationRefs[n]);
    if (locIn.length) { refs.push({ id: locationRefs[locIn[0]], role: 'place', name: locIn[0] }); used.location = locIn[0]; }
    // The previous frame, last, palette only — and only when there is room.
    if (a.prevId && refs.length < 5 && !refs.some((r) => r.id === a.prevId)) { refs.push({ id: a.prevId, role: 'palette', name: '' }); used.palette = true; }
    // The sentence names the references BY POSITION, so it is built from the
    // list rather than assumed.
    const parts = [];
    refs.forEach((r, i) => {
      const k = i + 1;
      if (r.role === 'user') parts.push('Reference image ' + k + ' is the producer\'s own photo and is GROUND TRUTH for that character: exactly the same face, hair, body and outfit.');
      else if (r.role === 'cast') parts.push('Reference image ' + k + ' is a character sheet of ' + r.name + ' shown from several angles: this character (a person, an animal or a creature, whatever the sheet shows) in the shot has EXACTLY that face or head, hair or markings, colours, build and wardrobe. Render ONE view of them inside the scene — never the sheet layout, never several copies, never the neutral backdrop.');
      else if (r.role === 'object') parts.push('Reference image ' + k + ' is a reference sheet of ' + r.name + ': the same object in the shot has exactly that design, colours, markings and materials — one instance, placed in the scene.');
      else if (r.role === 'place') parts.push('Reference image ' + k + ' is the PLACE (' + r.name + '): the same architecture, layout, landmarks, materials and the same arrangement of what stands where. Light, weather and time of day follow the text, not the plate; the plate is empty of people and its framing is not this shot\'s framing.');
      else if (r.role === 'palette') parts.push('The LAST reference image is only for colour palette and film look, never for layout and never for who or where anyone is.');
    });
    let prompt = a.prompt;
    if (parts.length) {
      prompt = parts.join(' ') + ' Compose the shot described here, which may place its subjects at any distance, angle or part of the location: ' + a.prompt;
      if (a.strict) prompt = 'STRICT MATCH — the previous attempt drifted from the references (' + String(a.strictNotes || 'identity or place did not match') + '). Wherever the text and the references disagree about how a person, object or place LOOKS, the references win. ' + prompt;
    }
    return { refs, used, prompt };
  }
  function apply(body, planned) {
    planned.refs.forEach((r, i) => { body['reference_' + (i + 1)] = r.id; });
    body.prompt = planned.prompt;
    return body;
  }
  return { norm, plan, apply, tagged };
})();
// ---------------------------------------------------------------------------
const planned = CONS.plan({ f: f, opts: opts, bible: bible, prompt: prompt, prevId: prevId, userRefId: userRefId, isFirstScene: isFirstScene, afterRefusal: rejectedBefore, strict: false, strictNotes: '' });
// count: 1 is mandatory (the API defaults to four); captchaRetry: 1 so a
// throttled account does not spend five captcha solves per request.
const body = CONS.apply({ email: 'fermafabiz@gmail.com', model: MODEL, prompt: prompt, aspectRatio: aspect, count: 1, captchaRetry: 1 }, planned);
console.log('IR refs for ' + scene.id + ': ' + (planned.refs.map((r) => r.role + (r.name ? '=' + r.name : '')).join(', ') || 'none'));
return [{ json: {
  sceneId: scene.id,
  prompt: prompt,
  requestBody: body,
  refs: planned.refs,
  usedReference: planned.refs.length ? planned.refs[0].id : null,
  refIsUser: planned.used.user,
  aspect: aspect,
} }];

// Same voice rules as AB Pick Voice in Media Generation — chapters mode
// picks the chapter's narrator, characters mode splits the text into tagged
// segments, everything else keeps the project narrator.
const pf = ($('VR Load Project').first().json || {}).fields || {};
const pv = String(pf['Voice ID'] || '');
const fallback = pv.includes('_') ? pv : 'elevenlabs_hpp4J3VqNfWAUOO0d1Us';
let voice = fallback, mode = 'off', cast = [], assign = {}, chapterVoices = {};
try {
  const opts = JSON.parse(pf['Editing Options'] || '{}') || {};
  mode = String(opts.multiVoiceMode || 'off');
  cast = (Array.isArray(opts.cast) ? opts.cast : []).filter(v => typeof v === 'string' && v.includes('_'));
  assign = (opts.castAssign && typeof opts.castAssign === 'object') ? opts.castAssign : {};
  // Explicit per-chapter narrators picked in the audio panel; the key is
  // the chapter number as a string, plus 'hook' for the opening scene.
  chapterVoices = (opts.chapterVoices && typeof opts.chapterVoices === 'object') ? opts.chapterVoices : {};
} catch (e) {}
const f = $('VR Load Scene').first().json.fields || {};
const text = String(f['Script Scenă'] || '');
if (mode === 'chapters' && (cast.length || Object.keys(chapterVoices).length)) {
  const o = Number(f['Ordine Scenă']);
  const chapter = Number.isFinite(o) ? Math.floor(o / 100) : 0;
  // An explicit pick always wins — including for the hook, which has
  // no position in the cast and otherwise keeps the main narrator.
  const picked = chapterVoices[chapter > 0 ? String(chapter) : 'hook'];
  if (typeof picked === 'string' && picked.includes('_')) voice = picked;
  else if (chapter > 0 && cast.length) voice = cast[(chapter - 1) % cast.length];
}
let multi = false, segments = [];
if (mode === 'characters' && cast.length) {
  const all = (($('VR Load All Scenes').first().json || {}).records || [])
    .sort((a, b) => (Number((a.fields || {})['Ordine Scenă']) || 0) - (Number((b.fields || {})['Ordine Scenă']) || 0));
  const order = [];
  for (const sc of all) {
    const t = String((sc.fields || {})['Script Scenă'] || '');
    for (const m of t.matchAll(/\[\s*CHARACTER:\s*([^\]]+)\]/gi)) {
      const n = m[1].trim();
      if (n && !order.includes(n)) order.push(n);
    }
  }
  const voiceFor = (name) => {
    const a = assign[name];
    if (typeof a === 'string' && a.includes('_')) return a;
    const i = order.indexOf(name);
    return cast[(i >= 0 ? i : 0) % cast.length];
  };
  let cur = fallback;
  for (const tk of text.split(/(\[[^\[\]]{1,60}\])/)) {
    if (/^\[\s*NARRATOR\s*\]$/i.test(tk)) { cur = fallback; continue; }
    const cm = tk.match(/^\[\s*CHARACTER:\s*([^\]]+)\]$/i);
    if (cm) { cur = voiceFor(cm[1].trim()); continue; }
    const t = tk.replace(/\s+/g, ' ').trim();
    if (!t) continue;
    const last = segments[segments.length - 1];
    if (last && last.voice_id === cur) last.text += ' ' + t;
    else segments.push({ text: t, voice_id: cur });
  }
  multi = segments.length > 0 && segments.some(s => s.voice_id !== fallback);
}
return [{ json: { voice_id: voice, multi, segments } }];

// Dialogue instructions for the writing prompts. Empty strings in every
// mode except 'characters', so classic projects render the exact same
// prompt text as before this node existed.
let mode = 'off', cast = [], narration = 'with', category = '', catOpts = {}, hookStyleWanted = '';
try {
  const pf = ($('Fetch Project Record').first().json || {}).fields || {};
  const o = JSON.parse(pf['Editing Options'] || '{}') || {};
  mode = String(o.multiVoiceMode || 'off');
  cast = Array.isArray(o.cast) ? o.cast : [];
  narration = String((o.categoryOptions || {}).narration || 'with');
  category = String(o.category || '');
  catOpts = (o.categoryOptions && typeof o.categoryOptions === 'object') ? o.categoryOptions : {};
  hookStyleWanted = String(o.hookStyle || '').trim().toLowerCase();
} catch (e) {}
// A silent film overrides every voice mode: nobody speaks at all.
const cinematic = category === 'cinematic';
const characters = !cinematic && mode === 'characters' && cast.length > 0;
const noNarrator = characters && narration === 'none';
const narrationRules = cinematic ? `\nSILENT FILM MODE — THIS FILM HAS NO NARRATION AND NO SPOKEN WORDS AT ALL (as important as the word count rule). This REPLACES rule 16 ("the voice says what the picture cannot"): here there is no voice, and the text IS the picture plan.\nThe text you write is a SILENT VISUAL BEAT SHEET: it is never spoken, never synthesized, never shown on screen. It exists only to drive the edit — each ~20-22 word beat becomes one 8-second shot, so the word count rule above still applies exactly.\nRules:\n(a) Terse, concrete, PRESENT-TENSE visual action — what the camera sees, one event per beat ("The black coupe snaps sideways into the hairpin, gravel spraying off the cliff edge").\n(b) No dialogue, no quotes, no inner thoughts, no addressing the viewer — nobody speaks in this film.\n(c) Every beat implies SOUND: engines, impacts, weather, footsteps, machinery — the film is carried entirely by the natural sound of what is on screen.\n(d) The story still escalates beat to beat like a real film: setup, build, payoff.\n` : !characters ? '' : noNarrator ? `\nDIALOGUE MODE — THIS FILM IS CHARACTER-DRIVEN, WITH NO NARRATOR AT ALL (as important as the word count rule).\nEvery single beat is SPOKEN by a Story Bible character; the tag [NARRATOR] is FORBIDDEN and must never appear. Rules:\n(a) Tag EVERY beat with its speaker at the start of the line, exactly: [CHARACTER: Name] — Name must match a Story Bible character name exactly. Never leave a line untagged.\n(b) Scene-setting, time jumps and transitions are carried by the characters themselves — what they say, notice, or react to — never by narration.\n(c) Dialogue is natural speech: contractions, hesitations, rhythm. Characters reveal the story by talking to each other; no exposition dumps, no character narrating facts at the camera.\n(d) Beats stay ~20-22 words (tags count as zero words); the total word count rule above still applies.\n(e) A character line is FIRST-PERSON SPEECH. Never write third-person narration inside a character tag — "he slides the stub into her notebook" is narration wearing a costume. If a beat cannot be said naturally by a character, rewrite it as something a character would actually say.\n` : `\nDIALOGUE MODE — THIS FILM IS CHARACTER-DRIVEN (as important as the word count rule).\nThe chapter is carried by the Story Bible characters SPEAKING to each other in direct dialogue. Rules:\n(a) 60-80% of the words are spoken lines; the narrator appears only in short connective beats (scene-setting, transitions), never to explain what dialogue could show.\n(b) Tag EVERY beat with its speaker at the start of the line, exactly: [NARRATOR] for narration, [CHARACTER: Name] for speech — Name must match a Story Bible character name exactly. Never leave a line untagged.\n(c) Dialogue is natural speech: contractions, hesitations, rhythm. Characters reveal the story by talking to each other; no exposition dumps, no character narrating facts at the camera.\n(d) Beats stay ~20-22 words (tags count as zero words); the total word count rule above still applies.\n`;
const segmentRules = cinematic ? `\nSILENT FILM MODE: narrator_text is a silent shot note — it is never spoken and never captioned — so keep it a terse description of the visible action. ALL storytelling lives in image_prompt and video_motion_prompt. In every video_motion_prompt make the action's SOUND read clearly from the visuals (a revving engine, screeching tires, pouring rain, a slamming door): the film's only audio is the natural sound of what is on screen.\n` : !characters ? '' : `\nDIALOGUE MODE: the chapter script contains speaker tags ${noNarrator ? '[CHARACTER: Name] (no narrator exists in this film)' : '[NARRATOR] and [CHARACTER: Name]'}. In narrator_text PRESERVE every tag verbatim: each copied line keeps its tag, and if you split a tagged passage across two scenes, repeat the tag at the start of the second part. A scene may contain several tagged lines. In every image prompt, put the SPEAKING character(s) on screen — paste their full visual_description — and match the shot to the exchange (over-the-shoulder for confrontations, close-up for whispered lines).\n`;
const hookRules = cinematic ? `\nTHIS FILM HAS NO NARRATION: nothing in the hook is spoken either. Only the SILENT hook styles are available (slate, action, cliffhanger) — every beat you write is a shot note the camera performs, never a line a voice reads.\n` : !noNarrator ? '' : `\nTHIS FILM HAS NO NARRATOR. The hook too is SPOKEN by a Story Bible character, in first person, and must start with its speaker tag exactly: [CHARACTER: Name] (Name matching the Story Bible). Never write untagged narration — untagged text would fall back to a narrator voice that does not exist in this film.\n`;
// KIDS STORY MODE is ADDITIVE: it composes with whatever voice mode is on
// (a silent kids film keeps the silent-film rules, a dialogue one keeps its
// tags) instead of replacing it, so the blocks below only ever APPEND.
// Non-kids projects append empty strings and render byte-identical prompts.
const kids = category === 'kids';
const kidsIllustrated = String(catOpts.visual_style || 'illustrated') !== 'cartoon3d';
const kidsStylePrefix = kidsIllustrated
  ? "Children's storybook illustration, soft watercolor and gouache textures, warm pastel palette, rounded friendly character shapes, gentle diffuse lighting"
  : 'High-quality 3D animated film still for children, soft rounded character design, expressive friendly faces, vivid warm colors, cinematic soft lighting';
const kidsNarration = !kids || cinematic ? '' : `
KIDS STORY MODE — this film is for young children (about ages 3-8) and every line is read aloud to them (as important as the word count rule).
(a) Short, simple sentences: one idea per sentence, everyday words a small child knows. No abstract vocabulary, no long clause chains.
(b) Warm and playful: the narrator is a storyteller by the bed, not a documentarian — gentle humour, wonder, and an occasional direct question to the little listener ("And do you know what the little fox did next?").
(c) Use repetition and rhythm the way picture books do: a recurring phrase or sound word children can anticipate and say along.
(d) NOTHING frightening: no death, no violence, no monsters played for fear, no peril without quick comfort. Tension stays mild and resolves kindly.
(e) The story still has a real arc — a lovable hero, a small problem, a warm ending with a gentle lesson worn lightly, never preached.
`;
const kidsSegment = !kids ? '' : `
KIDS STORY MODE — the film LOOKS like an animated children's film, never like photography.
(a) START every image_prompt with this exact style prefix, word for word, before anything else: "${kidsStylePrefix}". The style is the film's identity; a single photorealistic frame breaks it.
(b) Render every character and set description from the Story Bible IN that style: rounded, friendly proportions — no photorealistic humans anywhere in this film.
(c) In every video_motion_prompt keep movement gentle and easy to follow — a picture book coming softly to life, never fast or violent action.
`;
const kidsHook = !kids || cinematic || noNarrator ? '' : `
KIDS STORY: open like a storyteller inviting a child in — warm, curious, direct ("Have you ever wondered...?") — never dramatic or ominous.
`;

// ---- The hook: which style, and the rules for it ----
//
// The hook used to be one 18-22 word line over one 8-second shot, with the
// project TITLE typed over it. It is a small film of its own now: a style,
// one shot per beat, and an optional on-screen card. `Editing Options.hookStyle`
// decides — absent or 'auto' lets the model pick from what fits (every film
// gets a real hook either way), a named style forces it. The site's old
// `hookTitle` switch is not read any more.
//
// Three styles are SILENT (slate, action, cliffhanger): their beats are shot
// notes, prefixed [SILENT] by Prepend Hook To Chapters so the scene writer
// stores them with no narration and Media Generation makes no take for them.
// A silent film may only use those; a kids film may not use the two violent
// ones. The list is what Hook Guard enforces, so an unavailable style can
// never reach a scene however the model answers.
const HOOK_STYLES = ['teaser', 'question', 'figure', 'slate', 'action', 'cliffhanger'];
const SILENT_HOOK_STYLES = ['slate', 'action', 'cliffhanger'];
let hookAllowed;
// Absent reads as 'auto' — the same default the site's picker starts on
// (derive.ts normalizeHookStyle), so a film created before the picker
// existed and one that left it alone get the same opening.
if (HOOK_STYLES.includes(hookStyleWanted)) hookAllowed = [hookStyleWanted];
else hookAllowed = HOOK_STYLES.slice();
if (cinematic) hookAllowed = hookAllowed.filter((s) => SILENT_HOOK_STYLES.includes(s));
if (kids) hookAllowed = hookAllowed.filter((s) => ['teaser', 'question', 'slate'].includes(s));
if (!hookAllowed.length) hookAllowed = cinematic ? ['action'] : ['teaser'];
const hookForced = hookAllowed.length === 1;

const HOOK_STYLE_DEFS = {
  teaser: 'TEASER — 3 to 5 SPOKEN beats of 2-10 words each, one shot per beat. The most dramatic stretch of the story told like a trailer: present tense, concrete, each beat a step further in, and NEVER the outcome — the viewer must not learn how it ends. Example shape for a heist story: "One student. / A bank with three vaults. / Past the guards, alone. / Out with the money, and nobody suspects him." card stays empty.',
  question: 'QUESTION — 1 or 2 SPOKEN beats (3-12 words each) plus card.line1 = ONE question on screen, 3-12 words, ending with "?", that the film answers. card.line2 and card.source empty.',
  figure: 'FIGURE — 1 or 2 SPOKEN beats plus card.line1 = ONE number the film states (a year, a sum, a count), copied EXACTLY as the narration or the research pack writes it — never a number you computed or remembered; card.line2 = what it measures, at most 8 words; card.source = the evidence ref (E1..E20) when it comes from the research pack, else "".',
  slate: 'SLATE — exactly 1 SILENT shot note (8-25 words): the establishing frame of the story\'s main location as the bible describes it, no person near the camera, calm, with empty space in the centre of the frame for a title. card.line1 = the PLACE (at most 6 words), card.line2 = the DATE or time as the story states it (at most 6 words; leave "" if the story never states one — do not invent a date). Nothing is spoken.',
  action: 'ACTION — 2 or 3 SILENT shot notes (8-25 words each): the climax IN MOTION — what the protagonist does at the peak, each note one concrete visible action with its sound implied, no faces close to camera. Nothing is spoken; the story starts right after.',
  cliffhanger: 'CLIFFHANGER — 2 or 3 SILENT shot notes (8-25 words each): the moment BEFORE the catastrophe or the turn, tension rising shot by shot, ending on the frame just before the outcome — never the outcome itself. Nothing is spoken; the film then starts from the beginning.',
};
const hookStyleRules =
  '\nHOOK STYLE. ' + (hookForced
    ? 'The producer chose the style ' + hookAllowed[0].toUpperCase() + ' — use it and no other.'
    : 'Choose the ONE style that fits this story best from the list below and name it in "style".') +
  '\n' + hookAllowed.map((s) => '- ' + HOOK_STYLE_DEFS[s]).join('\n') +
  '\nA SPOKEN beat is a line the narrator says. A SILENT shot note is what the camera sees, present tense, never spoken — write it as a shot, not as prose.' +
  '\nThe hook may use only Story Bible characters and locations, and must not reveal how the story ends.\n';

// Handed to the segmenter for the hook chapter only (Ordine 0). The teaser
// is cut fast — a beat is a 2-4 second shot, not an 8-second scene — so the
// composition rules change: high contrast, one strong subject, motion that
// reads in a second.
const hookSegmentRules = `
THIS IS THE HOOK CHAPTER — the film's opening teaser, cut FAST. Every numbered line above is one SHOT of 2-4 seconds, not an 8-second scene, and the rules for this chapter override the ones below where they differ:
(a) scene_duration_seconds is 3 for every shot (6 for a shot whose line describes an empty establishing frame with room for a title).
(b) Composition for a shot that lasts three seconds: ONE strong subject, high contrast, dramatic light, tight or extreme framing — the kind of frame a trailer cuts to. No wide busy scenes that need time to read.
(c) video_motion_prompt: ONE decisive move that reads in a second — a fast push-in, a whip-pan, a hard tracking shot, a crash-zoom — and ONE clear action. Energy over subtlety. Keep the audio direction and the continuity rule exactly as elsewhere.
(d) A line starting with [SILENT] is a shot note, not narration: copy it VERBATIM as narrator_text (keep the [SILENT] prefix), and build the image and the motion from what it describes. Nothing in it is spoken.
(e) A line describing an establishing frame with space for a title: the image is wide, static-feeling, nobody near the camera, the centre of the frame uncluttered; the motion is a slow, steady drift only.
(f) Shots must differ hard from one another (location, subject, scale) — a teaser that shows the same frame three times is not a teaser.
`;
return [{ json: { mode, characters, noNarrator, cinematic, kids, castSize: cast.length, narrationRules: narrationRules + kidsNarration, segmentRules: segmentRules + kidsSegment, hookRules: hookRules + kidsHook, hookStyle: hookForced ? hookAllowed[0] : 'auto', hookStyleWanted: HOOK_STYLES.includes(hookStyleWanted) ? hookStyleWanted : 'auto', hookAllowed, hookForced, hookSilentStyles: SILENT_HOOK_STYLES, hookStyleRules, hookSegmentRules } }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('multi-voice TTS failed: ' + (j.error || 'unknown'));
if ($runIndex > 40) throw new Error('multi-voice TTS timed out after ' + $runIndex + ' polls. Last status: ' + s);
return [{ json: j }];

// Parse the research output into structured, sourced claims. Feeds three
// consumers: the Story Bible / narration / segmenter prompts (claimsList),
// the Evidence table (claims), and the thin-research flag on the project.
// The No Research branch flows through here too, yielding zero claims, so
// $('Extract Claims') is always safe to reference downstream.
const raw = String($json.output ?? '');
const researched = raw.trim() !== '' && !/^NO RESEARCH NEEDED/i.test(raw.trim());
const claims = [];
if (researched) {
  const re = /CLAIM:\s*(.+?)\s*\|\s*SOURCE:\s*(.+?)\s*\|\s*URL:\s*(\S+?)\s*(?:\|\s*DATE:\s*(.+?))?\s*$/gim;
  let m;
  while ((m = re.exec(raw)) !== null && claims.length < 20) {
    const url = m[3].replace(/[).,\]]+$/, '');
    // A claim without a resolvable URL is dropped, exactly as the prompt warns.
    if (!/^https?:\/\/\S+\.\S+/i.test(url)) continue;
    claims.push({
      ref: 'E' + (claims.length + 1),
      claim: m[1].trim(),
      source: m[2].trim(),
      url,
      date: (m[4] || '').trim() || 'n/a',
    });
  }
}
const notes = researched ? raw.replace(/^\s*CLAIMS:\s*$[\s\S]*/im, '').trim() : '';
const claimsList = claims
  .map((c) => `${c.ref}. ${c.claim} [${c.source} — ${c.url}${c.date !== 'n/a' ? ', ' + c.date : ''}]`)
  .join('\n');
// Under 6 claims on a researched topic = thin. The project gets flagged for
// manual review (Research Thin checkbox) but the script still proceeds.
const thin = researched && claims.length < 6;
const output = notes + (claimsList ? '\n\nSOURCED CLAIMS (ground truth, each with an ID):\n' + claimsList : '');
return [{ json: { output, notes, claims, claimsList, refs: claims.map((c) => c.ref), thin, researched } }];

// One Airtable create-batch (max 10 records) per output item. This node is
// IN-LINE on the way to Generate Story Bible (a canceled run used to lose
// its evidence because the parallel branch only flushed at the very end),
// so with zero claims it must still emit one passthrough item — returning
// [] here would stop the whole scripting chain for fiction projects.
const claims = $json.claims || [];
const pid = $('Receive Project Data').first().json.Project_ID;
const rows = claims.map((c) => ({
  fields: {
    'Claim': c.claim,
    'Ref': c.ref,
    'Source Name': c.source,
    'Source URL': c.url,
    'Source Date': c.date,
    'Project_ID': pid,
    'Proiect': [pid],
  },
}));
if (!rows.length) return [{ json: { records: [] } }];
const out = [];
for (let i = 0; i < rows.length; i += 10) out.push({ json: { records: rows.slice(i, i + 10) } });
return out;

// Evidence refs come from a model, so they are claims until proven: keep only
// refs that exist in the project's evidence pack, and flag scenes that made a
// factual claim the pack cannot back. With no research pack (fiction genres)
// every scene is forced to no-ref/unflagged.
const known = new Set($('Extract Claims').first().json.refs || []);
const items = $input.all();
// Under-delivery guard: Plan Scene Splits decided the scene count in code, so
// a shortfall here means the segmenter dropped narration on the floor (it did
// exactly that before the split moved into code). Nothing to auto-repair —
// the visuals only exist for the scenes it returned — but never let it pass
// unlogged the way it did in execution 877.
try {
  const planned = $('Plan Scene Splits').all().reduce((n, it) => n + (it.json.sceneCount || 0), 0);
  if (planned && items.length < planned) {
    console.log(`SCENE SHORTFALL: planned ${planned} scenes, segmenter returned ${items.length}. Narration was dropped.`);
  }
} catch (e) {}
for (const item of items) {
  const j = item.json;
  const required = j.evidence_required === true && known.size > 0;
  const cited = String(j.evidence_ref || '')
    .toUpperCase()
    .split(/[^E0-9]+/)
    .filter((r) => /^E\d+$/.test(r));
  const valid = [...new Set(cited)].filter((r) => known.has(r));
  j.evidence_required = required;
  j.evidence_ref = required ? valid.join(', ') : '';
  // Required but nothing real to cite -> the model invented or omitted its
  // source. The scene still ships; the flag routes it to human review.
  j.needs_fact_check = required && valid.length === 0;
}
// Continuity fields come from the model too: a location or character name
// that is not in the bible would attach no sheet and no plate, and the image
// pipeline must be able to trust a tag it finds. Keep only exact bible names
// (case- and diacritic-insensitive), drop the rest.
try {
  const bible = ($('Choose Bible').first().json || {}).bible || {};
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const canon = (list) => { const m = {}; (Array.isArray(list) ? list : []).forEach((e) => { const n = String((e || {}).name || '').trim(); if (n) m[norm(n)] = n; }); return m; };
  const chars = canon(bible.characters), objs = canon(bible.objects), locs = canon(bible.locations);
  const pick = (m, v) => m[norm(v)] || '';
  for (const item of items) {
    const j = item.json;
    j.location = pick(locs, j.location);
    j.characters = [...new Set((Array.isArray(j.characters) ? j.characters : []).map((c) => pick(chars, c)).filter(Boolean))];
    j.objects = [...new Set((Array.isArray(j.objects) ? j.objects : []).map((o) => pick(objs, o)).filter(Boolean))];
    j.time_of_day = /^(dawn|morning|day|afternoon|dusk|night|overcast|storm|interior)$/i.test(String(j.time_of_day || '')) ? String(j.time_of_day).toLowerCase() : '';
  }
  // Monotony, logged: 75 of the Burj Al Arab film's 86 scenes were "day" and
  // 46 sat on one location, which is what "extremely repetitive" looked like
  // from the inside. Nothing here can send a chapter back (the segmenter has
  // no retry loop), but the number must not pass unlogged.
  try {
    const tally = (key) => { const m = {}; for (const it of items) { const v = String(it.json[key] || '') || '(none)'; m[v] = (m[v] || 0) + 1; } return Object.entries(m).sort((a, b) => b[1] - a[1]); };
    if (items.length >= 8) {
      const [todTop] = tally('time_of_day'), [locTop] = tally('location');
      if (todTop && todTop[1] / items.length > 0.8) console.log('TOD MONOTONY: ' + todTop[1] + ' of ' + items.length + ' scenes in this chapter are "' + todTop[0] + '"');
      if (locTop && locTop[0] !== '(none)' && locTop[1] / items.length > 0.9 && items.length >= 12) console.log('LOCATION MONOTONY: ' + locTop[1] + ' of ' + items.length + ' scenes on "' + locTop[0] + '"');
    }
  } catch (e) {}
} catch (e) { console.log('continuity tags: bible unreadable, tags dropped — ' + e.message); for (const item of items) { item.json.location = ''; item.json.characters = []; item.json.objects = []; item.json.time_of_day = ''; } }
return items;

// Save Evidence emits one item per 10-claim batch (and its Airtable
// response). The Story Bible prompt reads $json.output, so collapse back
// to the Extract Claims payload — one item, prompt untouched.
return [{ json: $('Extract Claims').first().json }];

// The segmenter used to be TOLD a scene count and trusted to distribute the
// narration itself. gpt-5.4 quietly under-delivered: a 96-word chapter that
// asked for 5 scenes came back as ONE scene holding the first sentence, and
// the other 83 words vanished from the film (execution 877). Prompts cannot
// enforce this — so the split happens HERE, in code, and the model only
// writes visuals for text it is handed verbatim.
const WORDS_PER_SCENE = 22; // one 8-second beat
// The most a single scene may carry. A fold has no ceiling of its own — a
// runt merged into a full chunk simply becomes a long chunk — and the film
// pays for that at the very end of the pipeline, where the clip is stretched
// to the narration: on the 71-scene Boyd film one chunk came out at 34 words,
// which is 16.7 seconds of voice over an 8-second clip, and the assembler
// could only cover it with slow motion and then a frozen frame. 1.45x the
// target leaves the natural 27-28 word scenes alone and cuts only outliers.
const MAX_WORDS_PER_SCENE = Math.round(WORDS_PER_SCENE * 1.45);
const wc = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;

/**
 * Cut one span of text in two, as near its middle as a real boundary allows.
 *
 * `where` names the coarsest boundary to accept: a sentence end if there is
 * one, then clause punctuation, then a plain word gap for a run-on with no
 * punctuation at all. One owner, because both the unit splitter above and the
 * ceiling below need exactly this and a second copy would drift.
 */
function cutNear(u, where = 'sentence') {
  const res =
    where === 'word'
      ? [/\s+/g]
      : where === 'clause'
        ? [/[,;:—]\s+/g, /\s+/g]
        : [/(?<=[.!?]["”’')]*)\s+/g, /[,;:—]\s+/g, /\s+/g];
  for (const re of res) {
    const pos = [];
    let m;
    re.lastIndex = 0;
    while ((m = re.exec(u)) !== null) pos.push(m.index + m[0].length);
    if (!pos.length) continue;
    const mid = Math.floor(u.length / 2);
    let best = pos[0];
    for (const p of pos) if (Math.abs(p - mid) < Math.abs(best - mid)) best = p;
    const a = u.slice(0, best).trim();
    const b = u.slice(best).trim();
    if (a && b) return [a, b];
  }
  return null;
}

function planChunks(raw) {
  const text = String(raw || '').replace(/\s+/g, ' ').trim();
  const total = wc(text);
  if (!total) return [];
  let target = Math.max(1, Math.ceil(total / WORDS_PER_SCENE));
  let units = (text.match(/[^.!?]+(?:[.!?]+["”’')]*|$)/g) || [text])
    .map((s) => s.trim())
    .filter(Boolean);
  if (!units.length) units = [text];
  let ideal = total / target;
  // Cut over-long units: first to REACH the target count, then to stop any
  // single unit dwarfing the rest. Clause punctuation preferred; a run-on
  // with no punctuation at all falls back to a word boundary.
  for (let guard = 0; guard < 80; guard++) {
    const need = units.length < target;
    let bi = -1, bw = 0, byClause = true;
    for (let k = 0; k < units.length; k++) {
      const w = wc(units[k]);
      if (w <= bw) continue;
      const has = /[,;:—]\s/.test(units[k]);
      if (!has && w < ideal * 1.8) continue;
      if (!need && w <= ideal * 1.5) continue;
      bw = w; bi = k; byClause = has;
    }
    if (bi < 0) break;
    const cut = cutNear(units[bi], byClause ? 'clause' : 'word');
    if (!cut) break;
    units.splice(bi, 1, cut[0], cut[1]);
  }
  target = Math.min(target, units.length);
  const chunks = [];
  let idx = 0, rem = total;
  for (let c = 0; c < target; c++) {
    const remC = target - c;
    const maxTake = units.length - idx - (remC - 1);
    const want = rem / remC;
    let take = 1, w = wc(units[idx]);
    while (take < maxTake) {
      const nxt = wc(units[idx + take]);
      if (w >= want * 0.75 || w + nxt > want * 1.45) break;
      w += nxt; take++;
    }
    chunks.push(units.slice(idx, idx + take).join(' '));
    idx += take; rem -= w;
  }
  if (idx < units.length) chunks[chunks.length - 1] += ' ' + units.slice(idx).join(' ');
  // An 8-second shot carrying four words is dead air — fold runts away.
  const floor = Math.max(6, (total / chunks.length) * 0.4);
  let k = 0;
  while (chunks.length > 1 && k < chunks.length) {
    if (wc(chunks[k]) < floor) {
      const j = (k > 0 && (k === chunks.length - 1 || wc(chunks[k - 1]) <= wc(chunks[k + 1]))) ? k - 1 : k + 1;
      const lo = Math.min(k, j), hi = Math.max(k, j);
      chunks.splice(lo, hi - lo + 1, chunks[lo] + ' ' + chunks[hi]);
      k = 0;
    } else k++;
  }
  // …and now the other end of the same rule. Folding a runt away can only
  // make a chunk bigger, and nothing above ever checked how big — so this
  // splits anything over the ceiling back down, at a sentence boundary where
  // there is one. Bounded, because a chunk with no boundary inside it cannot
  // be cut and must be allowed to stand.
  for (let guard = 0; guard < 40; guard++) {
    const over = chunks.findIndex((c) => wc(c) > MAX_WORDS_PER_SCENE);
    if (over < 0) break;
    const cut = cutNear(chunks[over]);
    if (!cut) break;
    chunks.splice(over, 1, cut[0], cut[1]);
  }
  return chunks;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  // The HOOK chapter (Ordine 0) is written one line per shot by Prepend Hook
  // To Chapters, so it is cut on line breaks, never on word counts: a teaser
  // beat of four words is a whole shot on purpose, and folding it into its
  // neighbour would undo the hook. A hook that arrives without line breaks
  // (an older script, or one rejoined in the editor) falls back to the
  // ordinary chunking, so nothing older than this breaks.
  const isHook = Number((j.fields || {})['Ordine']) === 0;
  const hookLines = isHook ? String((j.fields || {})['Script Capitol'] || '').split(/\r?\n+/).map((s) => s.trim()).filter(Boolean) : [];
  const chunks = hookLines.length > 1 ? hookLines : planChunks(((j.fields || {})['Script Capitol']));
  const safe = chunks.length ? chunks : [String(((j.fields || {})['Script Capitol']) || '').trim()];
  console.log(`Chapter ${(j.fields || {})['Ordine']}: ${wc(((j.fields || {})['Script Capitol']))} words -> ${safe.length} scenes`);
  out.push({
    json: Object.assign({}, j, {
      sceneCount: safe.length,
      sceneChunks: safe,
      chunkList: safe.map((c, n) => `${n + 1}. ${c}`).join('\n'),
    }),
    // Save scenes To Airtable1 resolves the chapter record through
    // $('Create Chapter Records').item — keep the pairing intact.
    pairedItem: { item: i },
  });
}
return out;

// One item out, or the agent below runs once per scene.
//
// The scene list is taken from Validate Evidence Refs — the last node that has
// every scene in the order the film plays — and each scene is handed to the
// model with the SHOT and MOTION prompts beside its narration. Those two are
// the load-bearing half of the input: they are what lets the model see that a
// scene is already showing the thing it was about to draw, which is the
// mistake this whole feature was born from.
const items = $('Validate Evidence Refs').all();
const scenes = items.map((it, i) => {
  const j = it.json || {};
  const chapter = Number(j.chapter_number ?? 0);
  const scene = Number(j.scene_number ?? i + 1);
  return {
    index: i,
    // chapter*100 + scene, the convention every workflow already shares.
    order: chapter * 100 + scene,
    chapter,
    narration: String(j.narrator_text || ''),
    shot: String(j.image_prompt || ''),
    motion: String(j.video_motion_prompt || ''),
  };
});

let research = '';
try { research = String($('Extract Claims').first().json.output || ''); } catch (e) {}

let title = '';
let tone = '';
try {
  const p = $('Receive Project Data').first().json || {};
  title = String(p['Nume Proiect'] || p.name || p.Tema || '');
  tone = String(p.Tonalitate || p.tone || '');
} catch (e) {}

const brief = [
  `FILM: ${title}`,
  `TONE: ${tone}`,
  '',
  'SCENES (index · narration · what the shot will show)',
  ...scenes.map((s) => [
    `${s.index} · ${s.narration}`,
    `    SHOT: ${s.shot}`,
    `    MOTION: ${s.motion}`,
  ].join('\n')),
  '',
  'RESEARCH PACK (may be empty)',
  research || '(none — this film was not researched, so no fact from outside the script is available)',
].join('\n');

return [{ json: { brief, scenes, sceneCount: scenes.length } }];

