}
if (!chapters.length) throw new Error('The narration has no [CHAPTER n: title] blocks after ' + MAX_RETRIES + ' editor passes. Head: ' + text.slice(0, 300));
if (problems.length) console.log('NARRATION GUARD accepting after ' + MAX_RETRIES + ' retries with: ' + problems.join(' | '));
console.log('NARRATION GUARD ok: ' + chapters.length + ' chapters, ' + words + ' words (target ' + target + ', window ' + min + '-' + max + ')');
return [{ json: { output: text, retry: false, chapters, words, target, min, max } }];

// The hook is a small film of its own now — a style, one shot per beat and an
// optional card — and this guard is what makes the style RULES rules rather
// than requests. Everything here is measurable: beat counts, words per beat,
// the card fields a style needs, whether a figure or a date actually appears
// in the film or its research, and whether the hook leaks the ending. Same
// shape as Narration Guard: at most MAX_RETRIES rounds with the reason, then
// accept anyway, because a wrong hook still makes a film and nothing here may
// end a scripting run.
//
// The output carries the COMBINED NARRATION, not the hook: on a retry this
// item is what `Generate Hook` reads its prompt from, and that prompt wants
// $json.output.chapters. `Prepend Hook To Chapters` therefore takes the hook
// from `Generate Hook` by name instead.
const vm = $('Voice Mode').first().json;
const allowed = Array.isArray(vm.hookAllowed) && vm.hookAllowed.length ? vm.hookAllowed : ['teaser'];
const SILENT = Array.isArray(vm.hookSilentStyles) ? vm.hookSilentStyles : ['slate', 'action', 'cliffhanger'];
const combined = $('Combine Chapters').first().json.output;
const chapters = Array.isArray(combined.chapters) ? combined.chapters : [];
const hook = $json.output || {};
const MAX_RETRIES = 2;
const attempt = $runIndex + 1;
const wc = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;

const style = String(hook.style || '').trim().toLowerCase();
const beats = (Array.isArray(hook.beats) ? hook.beats : []).map((b) => String(b || '').replace(/\s+/g, ' ').trim()).filter(Boolean);
const card = hook.card && typeof hook.card === 'object' ? hook.card : {};
const line1 = String(card.line1 || '').trim();
const line2 = String(card.line2 || '').trim();
const source = String(card.source || '').trim();
const silent = SILENT.includes(style);

// Shape per style: [minBeats, maxBeats, minWordsPerBeat, maxWordsPerBeat].
const SHAPE = {
  teaser: [3, 5, 2, 10],
  question: [1, 2, 3, 12],
  figure: [1, 2, 3, 12],
  slate: [1, 1, 8, 25],
  action: [2, 3, 8, 25],
  cliffhanger: [2, 3, 8, 25],
};

const problems = [];
if (!allowed.includes(style)) {
  problems.push('style must be one of: ' + allowed.join(', ') + (style ? ' (got "' + style + '")' : ' (none given)'));
}
const shape = SHAPE[style] || SHAPE.teaser;
if (beats.length < shape[0] || beats.length > shape[1]) {
  problems.push('beats: ' + beats.length + ' given, this style needs ' + (shape[0] === shape[1] ? shape[0] : shape[0] + '-' + shape[1]));
}
beats.forEach((b, i) => {
  const w = wc(b);
  if (w < shape[2] || w > shape[3]) problems.push('beat ' + (i + 1) + ' is ' + w + ' words; each beat of this style is ' + shape[2] + '-' + shape[3]);
});

// What the film actually says, for the provenance checks below. Numbers are
// compared as digit strings so "1 200" and "1,200" both match "1200".
const filmText = chapters.map((c) => String(c.narrator_script || '')).join('\n');
let evidenceText = '';
try { evidenceText = JSON.stringify($('Extract Claims').first().json || {}); } catch (e) {}
// `min` is the shortest digit string that counts. The FIGURE check keeps
// single digits ("4 million" is a figure); the SPOILER check below asks for
// two or more, because a lone "3" turns up in every chapter and would flag
// the hook for nothing.
const digits = (s, min = 1) => (String(s || '').match(/\d[\d.,\s]*\d|\d/g) || []).map((n) => n.replace(/[^\d]/g, '')).filter((n) => n.length >= min);
const corpusDigits = new Set(digits(filmText).concat(digits(evidenceText)));

if (style === 'question') {
  if (wc(line1) < 3 || wc(line1) > 12 || !/\?\s*$/.test(line1)) problems.push('card.line1 must be one on-screen question of 3-12 words ending with "?"');
}
if (style === 'figure') {
  const nums = digits(line1);
  if (!nums.length) problems.push('card.line1 must contain the figure itself (a number)');
  else if (!nums.every((n) => corpusDigits.has(n))) problems.push('card.line1 shows "' + line1 + '", a figure the narration and the research never state — copy a number the film actually says, exactly as written');
  if (wc(line2) > 8) problems.push('card.line2 is ' + wc(line2) + ' words; at most 8');
  if (source && !new RegExp('\\b' + source.replace(/[^A-Za-z0-9]/g, '') + '\\b').test(evidenceText)) problems.push('card.source names ' + source + ', which is not in the research pack — leave it "" unless the figure comes from a listed claim');
}
if (style === 'slate') {
  if (!line1 || wc(line1) > 6) problems.push('card.line1 must name the PLACE in at most 6 words');
  if (wc(line2) > 6) problems.push('card.line2 must be the date or time in at most 6 words, or ""');
}
if (silent && beats.some((b) => /^\s*\[(NARRATOR|CHARACTER)/i.test(b))) problems.push('a silent style carries no speaker tags — beats are shot notes');

// The one rule every style shares, measured: a number that appears ONLY in
// the last chapter is the ending, and it may not be in the hook.
if (chapters.length > 1) {
  const lastDigits = new Set(digits(chapters[chapters.length - 1].narrator_script, 2));
  const earlier = new Set(digits(chapters.slice(0, -1).map((c) => c.narrator_script).join('\n'), 2));
  const hookDigits = digits(beats.join(' ') + ' ' + line1 + ' ' + line2, 2);
  const leaked = hookDigits.filter((n) => lastDigits.has(n) && !earlier.has(n));
  if (leaked.length) problems.push('the hook states ' + leaked.join(', ') + ', which appears only in the LAST chapter — that is the ending; take it out');
}

if (problems.length && attempt <= MAX_RETRIES) {
  const feedback = 'THE PREVIOUS ATTEMPT WAS REJECTED — ' + problems.join('; ') + '. Keep the same story, fix exactly these points.';
  console.log('HOOK GUARD retry ' + attempt + '/' + MAX_RETRIES + ' [' + style + ']: ' + problems.join(' | '));
  return [{ json: { output: combined, retry: true, hookFeedback: feedback, attempt } }];
}
if (problems.length) console.log('HOOK GUARD accepting after ' + MAX_RETRIES + ' retries [' + style + ']: ' + problems.join(' | '));
else console.log('HOOK GUARD ok [' + style + ']: ' + beats.length + ' beats, ' + wc(beats.join(' ')) + ' words');
return [{ json: { output: combined, retry: false, hookStyle: style, hookBeats: beats.length } }];

// Restore the stream. Save Hook Plan answers with a project id; Save Script
// To Airtable reads $json.output.chapters, so it has to be handed the item
// Prepend Hook To Chapters produced. Same move Motif Done and Evidence Done
// make for the same reason.
return [$('Prepend Hook To Chapters').first()];
